<?php
require __DIR__.'/../includes/achievement_board.php';
function check($v,$m){if(!$v)throw new RuntimeException($m);}
$c=ab_progression_config([]);check($c===['positive_step'=>10,'negative_step'=>5],'Default milestone steps');
foreach([[-11,0,2],[-10,0,2],[-9,0,1],[-5,0,1],[-4,0,0],[0,0,0],[9,0,0],[10,1,0],[19,1,0],[20,2,0],[29,2,0],[30,3,0],[40,4,0],[50,5,0],[60,6,0]] as [$points,$level,$reminder]){$r=ab_progression($points,$c);check($r['level']===$level&&$r['stars']===$level&&$r['reminder']===$reminder,'Exact inclusive milestone '.$points);check(in_array('shield',$r['gifts'],true)===($level>=2),'Shield removed below 20');check(in_array('crown',$r['gifts'],true)===($level>=3),'Crown threshold');check(in_array('wings',$r['gifts'],true)===($level>=4),'Wings threshold');if($points<10)check($r['gifts']===[],'No earned accessories below first tier');}
check(ab_progression(-10,$c)['recover_delta']===1&&ab_progression(-12,$c)['recover_delta']===3,'Clear path above negative boundary');check(ab_progression(19,$c)['next_delta']===1,'Positive progress to next level');
check(ab_progression_config(['progression'=>['positive_step'=>0,'negative_step'=>101]])===$c,'Corrupt config falls back safely');check(ab_progression(6,['positive_step'=>3,'negative_step'=>2])['level']===2,'Custom thresholds apply');
$s=ab_empty();$s['events']=[['id'=>'a','board'=>'b','date'=>'2026-11-27','at'=>'a','student_id'=>'s','student_name'=>'Synthetic','points'=>20],['id'=>'b','board'=>'b','date'=>'2026-11-27','at'=>'b','student_id'=>'s','student_name'=>'Synthetic','points'=>-1]];
$report=fn($state)=>ab_report($state,['s'=>['name'=>'Synthetic']],'b','2026-11-23','2026-11-29')['scores'][0];check($report($s)['progression']['level']===1,'Deduction below 20 removes tier 2 immediately');
$s['events'][0]['voided_at']='revision';$s['events'][]=['id'=>'c','board'=>'b','date'=>'2026-11-27','at'=>'c','student_id'=>'s','student_name'=>'Synthetic','points'=>10];check($report($s)['total']===9&&$report($s)['progression']['gifts']===[],'Edited original is excluded, rewards removed at 9');$s['events'][1]['voided_at']='undo';check($report($s)['total']===10&&$report($s)['progression']['level']===1,'Undo restores only the current earned tier');check(ab_report($s,['s'=>['name'=>'Synthetic']],'b','2026-12-01','2026-12-31')['scores'][0]['progression']['level']===0,'Levels follow the displayed reporting period');
echo "PASS achievement levels: positive/negative boundaries, custom steps, reversible gifts/stars, edit/undo recalculation and period isolation\n";
